# Sizing constants
# ─────────────────────────────────────────────────────────────────────────────
NAME_FS = 10
HEAD_FS = 11
BADGE_FS = 7
NN_FS = 8.5
ROW_H = 13
HEAD_H = 18
PADX = 5
COLGAP = 8
TABLE_GAP = 22          # room for FK "bus" lanes between tables
PANEL = dict(pad=10, head=26, gap=TABLE_GAP)
SUBPANEL = dict(pad=9, head=22, gap=TABLE_GAP)
AREA = dict(pad=16, head=16, foot=84, gap=16)
ROOT = dict(pad=50, head=110, gap=30)
LEG_ROW = 24


class Box:
    def __init__(self, kind: str, w: float = 0.0, h: float = 0.0, **kw):
        self.kind = kind
        self.w = w
        self.h = h
        self.x = self.y = 0.0
        self.ax = self.ay = 0.0
        self.children: list[Box] = []
        self.__dict__.update(kw)

    @property
    def container(self) -> bool:
        return self.kind in ("area", "panel")


def badges(column) -> list[str]:
    badge_list = []
    if column.pk:
        badge_list.append("PK")
    if column.fk:
        badge_list.append("FK")
    if column.unique and not column.pk:
        badge_list.append("UQ")
    return badge_list


def measure_table(t: Table) -> tuple[int, int, float, float]:
    name_widths, type_widths = [], []
    for c in t.columns:
        w = text_w(c.name, NAME_FS, c.pk)
        for badge in badges(c):
            w += 3 + text_w(badge, BADGE_FS, True)
        name_widths.append(w)
        type_widths.append(text_w(c.type, NAME_FS))
    max_name_width = max(name_widths, default=0)
    max_type_width = max(type_widths, default=0)
    has_nn = any(c.not_null or c.pk for c in t.columns)
    w = PADX + max_name_width + COLGAP + max_type_width + (COLGAP + text_w("not null", NN_FS) if has_nn else 0) + PADX
    w = max(w, text_w(t.name, HEAD_FS, True) + 2 * PADX + 6, 90)
    h = HEAD_H + len(t.columns) * ROW_H + 4
    return math.ceil(w), math.ceil(h), PADX + max_name_width + COLGAP, PADX + max_name_width + COLGAP + max_type_width + COLGAP


def skyline(rects: list[tuple[float, float]], W: float, gap: float) -> list[tuple[float, float]] | None:
    """Bottom-left skyline packing. rects = [(w,h)], returns [(x,y)] or None."""
    sky = [[0.0, 0.0, W + gap]]
    pos = []
    for w, h in rects:
        padded_w, padded_h = w + gap, h + gap
        best = None
        for i in range(len(sky)):
            x = sky[i][0]
            if x + padded_w > W + gap + 1e-6:
                break
            current_top, remaining_width, seg_idx = 0.0, padded_w, i
            while remaining_width > 1e-6 and seg_idx < len(sky):
                current_top = max(current_top, sky[seg_idx][1])
                remaining_width -= sky[seg_idx][2]
                seg_idx += 1
            if remaining_width > 1e-6:
                continue
            cand = (current_top + padded_h, x)
            if best is None or cand < best[0]:
                best = (cand, x, current_top)
        if best is None:
            return None
        _, x, y = best
        pos.append((x, y))
        new = []
        for seg_x, seg_y, seg_w in sky:
            seg_end = seg_x + seg_w
            if seg_end <= x + 1e-6 or seg_x >= x + padded_w - 1e-6:
                new.append([seg_x, seg_y, seg_w]); continue
            if seg_x < x:
                new.append([seg_x, seg_y, x - seg_x])
            if seg_end > x + padded_w:
                new.append([x + padded_w, seg_y, seg_end - (x + padded_w)])
        new.append([x, y + padded_h, padded_w])
        new.sort()
        merged: list = []
        for seg in new:
            if merged and abs(merged[-1][1] - seg[1]) < 1e-6 and abs(merged[-1][0] + merged[-1][2] - seg[0]) < 1e-6:
                merged[-1][2] += seg[2]
            else:
                merged.append(seg)
        sky = merged
    return pos


def pack(items: list[Box], gap: float, aspect: float, keep_order: bool = False) -> tuple[float, float]:
    """Place items to minimise wasted area near a target aspect ratio."""
    if not items:
        return 0.0, 0.0
    if len(items) == 1:
        items[0].x = items[0].y = 0.0
        return items[0].w, items[0].h
    order = list(items) if keep_order else sorted(items, key=lambda b: (-b.h, -b.w))
    rects = [(b.w, b.h) for b in order]
    wmax = max(w for w, _ in rects)
    wsum = sum(w for w, _ in rects) + gap * (len(rects) - 1)
    cands = {wmax, wsum}
    steps = 40
    for k in range(1, steps):
        cands.add(wmax + (wsum - wmax) * k / steps)
    acc = 0.0
    for w, _ in rects:  # natural row breaks
        acc += w + (gap if acc else 0)
        if acc >= wmax:
            cands.add(acc)
    best = None
    for W in sorted(cands):
        pos = skyline(rects, W, gap)
        if pos is None:
            continue
        best_width = max(x + w for (x, _), (w, _) in zip(pos, rects))
        best_height = max(y + h for (_, y), (_, h) in zip(pos, rects))
        score = best_width * best_height * (1 + 0.6 * abs(math.log((best_width / best_height) / aspect)))
        if best is None or score < best[0]:
            best = (score, pos, best_width, best_height)
    _, pos, best_width, best_height = best  # type: ignore[misc]
    for b, (x, y) in zip(order, pos):
        b.x, b.y = x, y
    return best_width, best_height


def fill_gaps(items: list[Box], W: float, H: float, gap: float) -> None:
    """Grow containers down, then right, into empty space (Magento's tidy look)."""
    conts = sorted([b for b in items if b.container], key=lambda b: (b.y, b.x))
    for c in conts:
        lim = H
        for o in items:
            if o is not c and o.x < c.x + c.w - 1e-6 and o.x + o.w > c.x + 1e-6 and o.y >= c.y + c.h - 1e-6:
                lim = min(lim, o.y - gap)
        c.h = max(c.h, lim - c.y)
    for c in sorted(conts, key=lambda b: (b.x, b.y)):
        lim = W
        for o in items:
            if o is not c and o.y < c.y + c.h - 1e-6 and o.y + o.h > c.y + 1e-6 and o.x >= c.x + c.w - 1e-6:
                lim = min(lim, o.x - gap)
        c.w = max(c.w, lim - c.x)


def legend_columns(sc: Schema, areas: list[str], hubs: dict) -> list[list[tuple[str, str]]]:
    cats = [k for k in CATEGORIES if any(t.category == k for t in sc.tables.values())]
    area_items = [("area", a) for a in areas]
    category_items = [("cat", k) for k in cats]
    if any(t.is_new for t in sc.tables.values()):
        category_items.append(("new", "Recently Added"))
    hub_items = [("hub", t) for t in hubs] + ([("hub_other", "other foreign keys")] if hubs else [])
    return [col for col in (area_items, category_items, hub_items) if col]


def legend_label(kind: str, v: str) -> str:
    if kind == "area":
        return f"Area:  {v}"
    if kind == "cat":
        return CATEGORIES[v][1]
    return v


def measure_legend(sc: Schema, areas: list[str], hubs: dict) -> tuple[int, int]:
    cols = legend_columns(sc, areas, hubs)
    widths = [max(text_w(legend_label(k, v), 12) for k, v in col) + 56 for col in cols]
    w = sum(widths) + 24 * (len(cols) - 1) + 40
    h = 70 + max(len(c) for c in cols) * LEG_ROW + 20
    return math.ceil(max(w, 260)), math.ceil(h)


def build_layout(
    sc: Schema,
    areas: list[str],
    area_color: dict[str, str],
    hubs: dict,
    aspect: float,
    keep_order: bool,
) -> tuple[Box, list[Box], Box, dict[str, Box]]:
    tree: OrderedDict = OrderedDict()
    for path, tables in sc.groups.items():
        node = tree
        for part in path:
            node = node.setdefault(part, OrderedDict({"__tables__": []}))
        node["__tables__"].extend(t for t in tables if t in sc.tables and sc.tables[t].path == path)

    table_boxes: dict[str, Box] = {}

    def make(name: str, node: OrderedDict, depth: int, color: str, path: tuple) -> Box:
        kids: list[Box] = []
        for t in node["__tables__"]:
            w, h, type_x, nn_x = measure_table(sc.tables[t])
            box = Box("table", w, h, table=sc.tables[t], type_x=type_x, nn_x=nn_x)
            table_boxes[t] = box
            kids.append(box)
        for child, sub in node.items():
            if child != "__tables__":
                kids.append(make(child, sub, depth + 1, color, path + (child,)))
        m = AREA if depth == 0 else (PANEL if depth == 1 else SUBPANEL)
        aspect_here = 0.9 if depth == 0 else 1.25
        inner_width, inner_height = pack(kids, m["gap"], aspect_here, keep_order)
        label_fs = 13 if depth == 1 else 11
        min_w = text_w(name.upper(), label_fs) + 24 if depth else 0
        box = Box(
            "area" if depth == 0 else "panel",
            kind_depth=depth, label=name, color=color,
            fill=shade(color, depth), m=m, path=path, children=kids,
            note=sc.group_notes.get(path, ""),
        )
        box.w = max(inner_width + 2 * m["pad"], min_w)
        box.h = inner_height + m["head"] + m.get("foot", m["pad"])
        return box

    area_boxes = [make(a, tree[a], 0, area_color[a], (a,)) for a in areas if a in tree]
    legend_width, legend_height = measure_legend(sc, areas, hubs)
    legend = Box("legend", legend_width, legend_height)
    items = area_boxes + [legend]
    inner_width, inner_height = pack(items, ROOT["gap"], aspect, keep_order=False)
    title = sc.title or "Database Diagram"
    inner_width = max(inner_width, text_w(title, 46) + 40)
    root = Box(
        "root",
        inner_width + 2 * ROOT["pad"],
        inner_height + ROOT["head"] + ROOT["pad"],
        children=items,
        title=title,
    )

    def finish(c: Box, W: float, H: float) -> None:
        fill_gaps(c.children, W, H, c.m["gap"] if hasattr(c, "m") else ROOT["gap"])
        for ch in c.children:
            if ch.container:
                finish(ch, ch.w - 2 * ch.m["pad"], ch.h - ch.m["head"] - ch.m.get("foot", ch.m["pad"]))

    root.m = dict(ROOT, foot=ROOT["pad"])
    finish(root, inner_width, inner_height)

    def place(c: Box, ox: float, oy: float) -> None:
        c.ax, c.ay = ox, oy
        m = c.m
        for ch in c.children:
            if ch.container:
                place(ch, ox + m["pad"] + ch.x, oy + m["head"] + ch.y)
            else:
                ch.ax, ch.ay = ox + m["pad"] + ch.x, oy + m["head"] + ch.y

    place(root, 0, 0)
    return root, area_boxes, legend, table_boxes
# ── routing ────────────────────────────────────────────────────────────────
def route_edges(sc: Schema, table_boxes: dict, hubs: dict) -> list[dict]:
    def port_y(box, col: str) -> float:
        i = box.table.col_index(col)
        return box.ay + HEAD_H / 2 if i is None else box.ay + HEAD_H + 2 + i * ROW_H + ROW_H / 2

    lanes: dict = {}

    def lane(key, slot) -> int:
        lst = lanes.setdefault(key, [])
        if slot not in lst:
            lst.append(slot)
        return lst.index(slot)

    max_lanes = max(1, int((TABLE_GAP - 8) / 4))
    edges = []
    for i, r in enumerate(sc.refs):
        source_box = table_boxes.get(r.child)
        target_box = table_boxes.get(r.parent)
        if not source_box or not target_box:
            print(
                f"warning: ref {r.child}.{r.child_col} -> {r.parent}.{r.parent_col}: unknown table, skipped",
                file=sys.stderr,
            )
            continue
        source_y = port_y(source_box, r.child_col)
        target_y = port_y(target_box, r.parent_col)
        color = r.color or hubs.get(r.parent, DEFAULT_EDGE)
        source_left = source_box.ax
        source_right = source_box.ax + source_box.w
        target_left = target_box.ax
        target_right = target_box.ax + target_box.w
        if target_left >= source_right - 1e-6:  # target to the right
            k = lane((r.parent, "L"), r.parent_col) % max_lanes
            lx = target_left - 6 - 4 * k
            pts = [(source_right, source_y), (lx, source_y), (lx, target_y), (target_left, target_y)]
        elif target_right <= source_left + 1e-6:  # target to the left
            k = lane((r.parent, "R"), r.parent_col) % max_lanes
            lx = target_right + 6 + 4 * k
            pts = [(source_left, source_y), (lx, source_y), (lx, target_y), (target_right, target_y)]
        else:  # stacked / self-ref: loop on the right
            k = lane((r.parent, "R"), r.parent_col) % max_lanes
            lx = max(source_right, target_right) + 6 + 4 * k
            pts = [(source_right, source_y), (lx, source_y), (lx, target_y), (target_right, target_y)]
        edges.append(dict(
            i=len(edges), s=r.child, sc=r.child_col,
            t=r.parent, tc=r.parent_col,
            color=color, pts=pts, kind=r.kind,
        ))
    return edges
# ── render_svg ────────────────────────────────────────────────────────────────
def esc(s) -> str:
    return html.escape(str(s), quote=True)


def render_table(table_box: Box, hubs: dict, interactive: bool) -> list[str]:
    t = table_box.table
    x, y, w, h = table_box.ax, table_box.ay, table_box.w, table_box.h
    head_bg = CATEGORIES[t.category][0] if t.category else (t.headercolor or "#ffffff")
    head_fg = "#000" if luminance(head_bg) > 0.5 else "#fff"
    dash = ' stroke-dasharray="5 3"' if t.is_new else ""
    sw = 2 if t.is_new else 1.2
    out = [f'<g class="tbl" data-t="{esc(t.name)}">']
    hub = hubs.get(t.name)
    if hub:  # Magento's coloured disc behind the corner
        r = min(20, w / 4)
        out.append(
            f'<circle cx="{x + w - r * 0.4:.1f}" cy="{y + HEAD_H * 0.6:.1f}" r="{r:.1f}" '
            f'fill="{hub}" stroke="#000" stroke-width="1"/>'
        )
    out += [
        f'<rect x="{x}" y="{y}" width="{w}" height="{h}" fill="#fff" stroke="#000" stroke-width="{sw}"{dash}/>',
        f'<rect x="{x}" y="{y}" width="{w}" height="{HEAD_H}" fill="{head_bg}" stroke="#000" stroke-width="{sw}"{dash}/>',
        f'<text x="{x + w / 2}" y="{y + 13}" text-anchor="middle" font-family="{SANS}" '
        f'font-size="{HEAD_FS}" font-weight="bold" fill="{head_fg}">{esc(t.name)}</text>',
    ]
    for i, c in enumerate(t.columns):
        ry = y + HEAD_H + 2 + i * ROW_H
        base = ry + ROW_H - 3
        deco = ' font-weight="bold" text-decoration="underline"' if c.pk else ""
        parts = [f'<tspan{deco}>{esc(c.name)}</tspan>']
        for bd in badges(c):
            parts.append(f'<tspan dx="3" font-size="{BADGE_FS}" font-weight="bold" fill="#666">{bd}</tspan>')
        out.append(
            f'<text x="{x + PADX}" y="{base}" font-family="{SANS}" font-size="{NAME_FS}">{"".join(parts)}</text>'
        )
        out.append(
            f'<text x="{x + table_box.type_x}" y="{base}" font-family="{SANS}" '
            f'font-size="{NAME_FS}" fill="{TYPE_COLOR}">{esc(c.type)}</text>'
        )
        if c.not_null or c.pk:
            out.append(
                f'<text x="{x + table_box.nn_x}" y="{base}" font-family="{SANS}" '
                f'font-size="{NN_FS}" fill="{NOTNULL_COLOR}">not null</text>'
            )
        if interactive:
            if c.note:
                out.append(f'<circle cx="{x + 2.2}" cy="{ry + ROW_H / 2}" r="1.6" fill="#2f5f8a"/>')
            out.append(
                f'<rect class="row" data-c="{esc(c.name)}" x="{x}" y="{ry}" '
                f'width="{w}" height="{ROW_H}" fill="#000" fill-opacity="0"/>'
            )
    if interactive and t.note:
        out.append(f'<path d="M{x + w - 9},{y + 1} h8 v8 z" fill="#2f5f8a"/>')
    out.append("</g>")
    return out


def render_container(container_box: Box, out: list[str], labels: list[str]) -> None:
    depth = container_box.kind_depth
    if depth == 0:
        pen, rx = mix(container_box.color, "#000", 0.35), 34
        fg = "#fff" if luminance(container_box.fill) < 0.42 else "#000"
        out.append(
            f'<g class="area" data-area="{esc(container_box.label)}"><rect x="{container_box.ax}" y="{container_box.ay}" '
            f'width="{container_box.w}" height="{container_box.h}" rx="{rx}" fill="{container_box.fill}" stroke="{pen}" stroke-width="3"/>'
        )
        fs = min(58, (container_box.w - 40) / max(1, text_w(container_box.label.upper(), 1, True)))
        out.append("</g>")
        labels.append(
            f'<text x="{container_box.ax + container_box.w / 2}" y="{container_box.ay + container_box.h - 24}" text-anchor="middle" '
            f'font-family="{SERIF}" font-size="{fs:.1f}" fill="{fg}" pointer-events="none">'
            f'{esc(container_box.label.upper())}</text>'
        )
    else:
        pen = mix(container_box.fill, "#000", 0.28)
        fg = "#fff" if luminance(container_box.fill) < 0.42 else "#000"
        fs = 13 if depth == 1 else 11
        out.append(
            f'<g class="panel" data-path="{esc(" › ".join(container_box.path))}"><rect x="{container_box.ax}" y="{container_box.ay}" '
            f'width="{container_box.w}" height="{container_box.h}" rx="{16 if depth == 1 else 12}" fill="{container_box.fill}" '
            f'stroke="{pen}" stroke-width="1.4"/>'
        )
        out.append("</g>")
        labels.append(
            f'<text x="{container_box.ax + container_box.w / 2}" y="{container_box.ay + (17 if depth == 1 else 15)}" text-anchor="middle" '
            f'font-family="{SERIF}" font-size="{fs}" fill="{fg}" pointer-events="none">'
            f'{esc(container_box.label.upper())}</text>'
        )
    for ch in container_box.children:
        if ch.container:
            render_container(ch, out, labels)


def render_legend(b: Box, sc: Schema, areas: list[str], area_color: dict, hubs: dict) -> list[str]:
    out = [
        f'<g class="legend"><rect x="{b.ax}" y="{b.ay}" width="{b.w}" height="{b.h}" rx="22" '
        f'fill="#fff" stroke="#000" stroke-width="3"/>',
        f'<text x="{b.ax + b.w - 22}" y="{b.ay + 48}" text-anchor="end" font-family="{SERIF}" '
        f'font-size="36">LEGEND</text>',
    ]
    x = b.ax + 20
    for col in legend_columns(sc, areas, hubs):
        y = b.ay + 76
        cw = max(text_w(legend_label(k, v), 12) for k, v in col) + 56
        for kind, v in col:
            if kind == "area":
                c = area_color[v]
                for i in range(3):
                    out.append(
                        f'<rect x="{x + i * 13}" y="{y}" width="14" height="20" rx="3" '
                        f'fill="{shade(c, i)}" stroke="#444" stroke-width=".6"/>'
                    )
            elif kind == "cat":
                c = CATEGORIES[v][0]
                out.append(
                    f'<rect x="{x + 6}" y="{y}" width="24" height="20" fill="{c}" stroke="#000" stroke-width="1.4"/>'
                    f'<line x1="{x + 6}" y1="{y + 5}" x2="{x + 30}" y2="{y + 5}" stroke="#000" stroke-width="1.2"/>'
                )
            elif kind == "new":
                out.append(
                    f'<rect x="{x + 6}" y="{y}" width="24" height="20" fill="#fff" stroke="#000" '
                    f'stroke-width="1.6" stroke-dasharray="3 2"/>'
                )
            else:
                c = hubs.get(v, DEFAULT_EDGE) if kind == "hub" else DEFAULT_EDGE
                out.append(
                    f'<rect x="{x}" y="{y + 5}" width="40" height="9" fill="{c}" stroke="#000" stroke-width="1"/>'
                )
            italic = ' font-style="italic"' if kind == "hub_other" else ""
            out.append(
                f'<text x="{x + 48}" y="{y + 15}" font-family="{SANS}" font-size="12"{italic}>'
                f'{esc(legend_label(kind, v))}</text>'
            )
            y += LEG_ROW
        x += cw + 24
    out.append("</g>")
    return out


def render_svg(
    sc: Schema,
    root: Box,
    areas: list[str],
    area_boxes: list[Box],
    legend: Box,
    table_boxes: dict[str, Box],
    area_color: dict[str, str],
    hubs: dict,
    edges: list[dict],
    interactive: bool,
) -> tuple[str, int, int]:
    W, H = math.ceil(root.w), math.ceil(root.h)
    size = "" if interactive else f' width="{W}" height="{H}"'
    out = [
        f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 {W} {H}"{size} '
        f'preserveAspectRatio="xMidYMid meet">'
    ]
    colors = sorted({e["color"] for e in edges})
    out.append("<defs>")
    for c in colors:
        mid = "a" + c.lstrip("#")
        out.append(
            f'<marker id="{mid}" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" '
            f'markerUnits="userSpaceOnUse" orient="auto"><path d="M0,0 L10,5 L0,10 z" fill="{c}"/></marker>'
        )
    out.append("</defs>")
    out.append(
        f'<rect x="4" y="4" width="{W - 8}" height="{H - 8}" rx="140" fill="#e6e9ec" stroke="#000" stroke-width="5"/>'
    )
    out.append(
        f'<text x="{W / 2}" y="92" text-anchor="middle" font-family="{SERIF}" '
        f'font-size="46">{esc(root.title)}</text>'
    )
    labels: list[str] = []
    for a in area_boxes:
        render_container(a, out, labels)
    out.extend(render_legend(legend, sc, areas, area_color, hubs))

    out.append('<g id="edges" fill="none" stroke-linejoin="round">')
    for e in edges:
        d = "M" + " L".join(f"{x:.1f},{y:.1f}" for x, y in e["pts"])
        dash = ' stroke-dasharray="6 3"' if e["kind"] == "<>" else ""
        out.append(
            f'<path class="edge" data-i="{e["i"]}" d="{d}" stroke="{e["color"]}" stroke-width="1.3"'
            f'{dash} marker-end="url(#a{e["color"].lstrip("#")})"/>'
        )
    out.append("</g>")

    out.extend(labels)
    out.append('<g id="tables">')
    for table_box in table_boxes.values():
        out.extend(render_table(table_box, hubs, interactive))
    out.append("</g>")
    out.append("</svg>")
    return "\n".join(out), W, H
