# ── pdf ────────────────────────────────────────────────────────────────
def write_pdf(svg_text: str, W: int, H: int, path: str) -> str:
    """Write a PDF using one of three optional backends."""
    try:
        import cairosvg  # type: ignore
        cairosvg.svg2pdf(bytestring=svg_text.encode(), write_to=path)
        return "cairosvg"
    except ImportError:
        pass
    if shutil.which("rsvg-convert"):
        subprocess.run(["rsvg-convert", "-f", "pdf", "-o", path], input=svg_text.encode(), check=True)
        return "rsvg-convert"
    try:
        from playwright.sync_api import sync_playwright  # type: ignore
        with sync_playwright() as p:
            b = p.chromium.launch()
            pg = b.new_page()
            pg.set_content(f'<html><body style="margin:0">{svg_text}</body></html>')
            pg.pdf(path=path, width=f"{W}px", height=f"{H}px", print_background=True,
                   margin=dict(top="0", right="0", bottom="0", left="0"))
            b.close()
        return "Chromium"
    except ImportError:
        sys.exit(
            "No PDF backend found. Either `pip install cairosvg`, install rsvg-convert, "
            "or open the .html file and use the PDF button (browser → Save as PDF)."
        )
# ── introspect ────────────────────────────────────────────────────────────────
"""dbml-atlas introspect — read a live database and emit DBML to stdout.

Supported backends (all optional):
  sqlite3   stdlib — always available
  psycopg2  pip install dbml-atlas[postgres]
  pymysql   pip install dbml-atlas[mysql]

Usage:
  dbml-atlas introspect sqlite:///path/to/file.db
  dbml-atlas introspect postgresql://user:pass@host/db
  dbml-atlas introspect mysql://user:pass@host/db
"""



def _connect(dsn: str):
    """Return (connection, dialect) or exit with a helpful message."""
    if dsn.startswith("sqlite:///"):
        import sqlite3
        path = dsn[len("sqlite:///"):]
        return sqlite3.connect(path), "sqlite"
    if dsn.startswith("postgresql://") or dsn.startswith("postgres://"):
        try:
            import psycopg2  # type: ignore
        except ImportError:
            sys.exit("psycopg2 not installed. Run: pip install dbml-atlas[postgres]")
        return psycopg2.connect(dsn), "postgres"
    if dsn.startswith("mysql://"):
        try:
            import pymysql  # type: ignore
        except ImportError:
            sys.exit("pymysql not installed. Run: pip install dbml-atlas[mysql]")
        url = dsn[len("mysql://"):]
        m = re.match(r"(?:([^:@]+)(?::([^@]*))?@)?([^:/]+)(?::(\d+))?/(.+)", url)
        if not m:
            sys.exit(f"Cannot parse MySQL DSN: {dsn}")
        user, pw, host, port, db = m.groups()
        return pymysql.connect(host=host, user=user, password=pw or "", database=db,
                               port=int(port or 3306)), "mysql"
    sys.exit(f"Unsupported DSN scheme. Use sqlite:///, postgresql://, or mysql://")


def _columns_sqlite(cur, table: str) -> list[dict]:
    cur.execute(f"PRAGMA table_info({table})")
    cols = []
    for row in cur.fetchall():
        cols.append(dict(
            name=row[1], type=row[2] or "text",
            pk=bool(row[5]), not_null=bool(row[3]),
            default=str(row[4]) if row[4] is not None else None,
        ))
    return cols


def _columns_postgres(cur, table: str) -> list[dict]:
    cur.execute("""
        SELECT c.column_name, c.data_type, c.is_nullable, c.column_default,
               CASE WHEN pk.column_name IS NOT NULL THEN true ELSE false END
        FROM information_schema.columns c
        LEFT JOIN (
            SELECT ku.column_name FROM information_schema.table_constraints tc
            JOIN information_schema.key_column_usage ku
              ON tc.constraint_name=ku.constraint_name AND tc.table_name=ku.table_name
            WHERE tc.constraint_type='PRIMARY KEY' AND tc.table_name=%s
        ) pk ON c.column_name=pk.column_name
        WHERE c.table_name=%s AND c.table_schema='public'
        ORDER BY c.ordinal_position
    """, (table, table))
    return [dict(name=r[0], type=r[1], not_null=r[2] == "NO",
                 default=r[3], pk=bool(r[4])) for r in cur.fetchall()]


def _columns_mysql(cur, table: str, db: str) -> list[dict]:
    cur.execute("""
        SELECT COLUMN_NAME, DATA_TYPE, IS_NULLABLE, COLUMN_DEFAULT, COLUMN_KEY
        FROM information_schema.COLUMNS
        WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s
        ORDER BY ORDINAL_POSITION
    """, (db, table))
    return [dict(name=r[0], type=r[1], not_null=r[2] == "NO",
                 default=r[3], pk=r[4] == "PRI") for r in cur.fetchall()]


def _fks_sqlite(cur, table: str) -> list[dict]:
    cur.execute(f"PRAGMA foreign_key_list({table})")
    return [dict(from_col=r[3], to_table=r[2], to_col=r[4]) for r in cur.fetchall()]


def _fks_postgres(cur, table: str) -> list[dict]:
    cur.execute("""
        SELECT kcu.column_name, ccu.table_name, ccu.column_name
        FROM information_schema.table_constraints tc
        JOIN information_schema.key_column_usage kcu
          ON tc.constraint_name=kcu.constraint_name AND tc.table_schema=kcu.table_schema
        JOIN information_schema.constraint_column_usage ccu
          ON ccu.constraint_name=tc.constraint_name AND ccu.table_schema=tc.table_schema
        WHERE tc.constraint_type='FOREIGN KEY' AND tc.table_name=%s AND tc.table_schema='public'
    """, (table,))
    return [dict(from_col=r[0], to_table=r[1], to_col=r[2]) for r in cur.fetchall()]


def _fks_mysql(cur, table: str, db: str) -> list[dict]:
    cur.execute("""
        SELECT COLUMN_NAME, REFERENCED_TABLE_NAME, REFERENCED_COLUMN_NAME
        FROM information_schema.KEY_COLUMN_USAGE
        WHERE TABLE_SCHEMA=%s AND TABLE_NAME=%s AND REFERENCED_TABLE_NAME IS NOT NULL
    """, (db, table))
    return [dict(from_col=r[0], to_table=r[1], to_col=r[2]) for r in cur.fetchall()]


def introspect(dsn: str) -> str:
    """Connect to a database and return DBML text."""
    conn, dialect = _connect(dsn)
    cur = conn.cursor()

    if dialect == "sqlite":
        cur.execute("SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%' ORDER BY name")
        tables = [r[0] for r in cur.fetchall()]
    elif dialect == "postgres":
        cur.execute("SELECT table_name FROM information_schema.tables WHERE table_schema='public' ORDER BY table_name")
        tables = [r[0] for r in cur.fetchall()]
    else:  # mysql
        db = dsn.rsplit("/", 1)[-1]
        cur.execute("SELECT table_name FROM information_schema.tables WHERE table_schema=%s ORDER BY table_name", (db,))
        tables = [r[0] for r in cur.fetchall()]

    lines = [f"// Generated by dbml-atlas introspect from {dsn.split('@')[-1]}", ""]
    refs: list[str] = []

    for table in tables:
        if dialect == "sqlite":
            cols = _columns_sqlite(cur, table)
            fks = _fks_sqlite(cur, table)
        elif dialect == "postgres":
            cols = _columns_postgres(cur, table)
            fks = _fks_postgres(cur, table)
        else:
            db = dsn.rsplit("/", 1)[-1]
            cols = _columns_mysql(cur, table, db)
            fks = _fks_mysql(cur, table, db)

        fk_cols = {f["from_col"] for f in fks}
        lines.append(f"Table {table} {{")
        for c in cols:
            settings = []
            if c["pk"]:
                settings.append("pk")
            if c["not_null"] and not c["pk"]:
                settings.append("not null")
            if c["default"] is not None:
                dv = c["default"]
                settings.append(f"default: `{dv}`" if re.search(r"[()']", dv) else f"default: {dv!r}")
            if c["name"] in fk_cols:
                fk = next(f for f in fks if f["from_col"] == c["name"])
                settings.append(f"ref: > {fk['to_table']}.{fk['to_col']}")
            bracket = f" [{', '.join(settings)}]" if settings else ""
            lines.append(f"  {c['name']}  {c['type']}{bracket}")
        lines.append("}")
        lines.append("")

    conn.close()
    return "\n".join(lines)
# ── suggest ────────────────────────────────────────────────────────────────
def suggest_groups(sc: Schema) -> str:
    """
    Analyse table names and FK relationships to suggest TableGroup blocks.

    Algorithm:
    1. Prefix clustering — tables sharing the same leading snake_case segment(s) form a group.
       Two-segment prefixes are tried first (e.g. "shop_staff" + "shop_notes" → "Shop"),
       then one-segment as a fallback.
    2. FK affinity — tables that didn't land in a prefix group attach to whichever existing
       group they share the most FK edges with.
    3. Connected components — any tables still ungrouped are clustered by FK reachability.
       Each component is named after its most-connected member.
    4. Output — ready-to-paste DBML TableGroup blocks with palette colours.
    """
    tables = list(sc.tables.keys())
    if not tables:
        return "// No tables found.\n"

    # Undirected FK adjacency (both child→parent and parent→child)
    adj: dict[str, set[str]] = defaultdict(set)
    for r in sc.refs:
        if r.child in sc.tables and r.parent in sc.tables:
            adj[r.child].add(r.parent)
            adj[r.parent].add(r.child)

    # ── 1. Prefix clustering ──────────────────────────────────────────────────
    # Try two-segment prefixes first so "plan_addon_prices" and "plan_addons"
    # both land in "Plan Addon" rather than just "Plan", when that's more specific.
    assigned: dict[str, str] = {}   # table → group name
    groups: dict[str, list[str]] = {}  # group name → [tables]

    for n_segs in (2, 1):
        prefix_map: dict[str, list[str]] = defaultdict(list)
        for name in tables:
            if name in assigned:
                continue
            parts = name.split("_")
            if len(parts) >= n_segs:
                prefix_map["_".join(parts[:n_segs])].append(name)

        for prefix, members in sorted(prefix_map.items()):
            unassigned = [m for m in members if m not in assigned]
            if len(unassigned) >= 2:
                g = prefix.replace("_", " ").title()
                if g not in groups:
                    groups[g] = []
                groups[g].extend(unassigned)
                for m in unassigned:
                    assigned[m] = g

    # ── 2. FK affinity ────────────────────────────────────────────────────────
    # Single tables not caught by prefix → attach to the group with the most
    # shared FK edges.  Do multiple passes until no more can be attached.
    changed = True
    while changed:
        changed = False
        for t in [t for t in tables if t not in assigned]:
            scores: Counter[str] = Counter()
            for nb in adj[t]:
                if nb in assigned:
                    scores[assigned[nb]] += 1
            if scores:
                best = scores.most_common(1)[0][0]
                groups[best].append(t)
                assigned[t] = best
                changed = True

    # ── 3. Connected components of remaining ungrouped ────────────────────────
    ungrouped = [t for t in tables if t not in assigned]
    if ungrouped:
        ug_set = set(ungrouped)
        visited: set[str] = set()
        for start in ungrouped:
            if start in visited:
                continue
            comp: list[str] = []
            stack = [start]
            while stack:
                node = stack.pop()
                if node in visited:
                    continue
                visited.add(node)
                if node in ug_set:
                    comp.append(node)
                    for nb in adj[node]:
                        if nb in ug_set and nb not in visited:
                            stack.append(nb)
            if not comp:
                continue
            # Name after the member with the most FK connections in the whole graph
            rep = max(comp, key=lambda t: len(adj[t]))
            g = rep.split("_")[0].title()
            base, n = g, 2
            while g in groups:
                g = f"{base}{n}"
                n += 1
            groups[g] = sorted(comp)
            for t in comp:
                assigned[t] = g

    # ── 4. Emit DBML ──────────────────────────────────────────────────────────
    lines = [
        "// Suggested TableGroups — generated by: dbml-atlas suggest-groups <file>",
        "// Review group names, adjust nesting with __ (e.g. Sales__Orders),",
        "// then paste into your DBML file.",
        "",
    ]
    for i, (g_name, members) in enumerate(groups.items()):
        color = AREA_PALETTE[i % len(AREA_PALETTE)]
        # DBML group names can't have spaces — use underscores, path separator stays __
        dbml_name = g_name.replace(" ", "_")
        lines.append(f'TableGroup {dbml_name} [color: "{color}"] {{')
        for m in sorted(members):
            lines.append(f"  {m}")
        lines.append("}")
        lines.append("")

    return "\n".join(lines)
# ── cli ────────────────────────────────────────────────────────────────
def _filter_area(sc, area_name: str) -> None:
    """Remove all tables not in the given area, and their dangling refs/groups."""
    keep = {name for name, t in sc.tables.items() if t.path and t.path[0] == area_name}
    if not keep:
        available = ", ".join(sorted({t.path[0] for t in sc.tables.values() if t.path}))
        sys.exit(f"Area '{area_name}' not found. Available areas: {available}")
    sc.tables = OrderedDict((k, v) for k, v in sc.tables.items() if k in keep)
    sc.refs = [r for r in sc.refs if r.child in keep and r.parent in keep]
    sc.groups = OrderedDict(
        (p, [t for t in ts if t in keep])
        for p, ts in sc.groups.items()
        if p and p[0] == area_name and any(t in keep for t in ts)
    )


def main() -> None:
    parser = argparse.ArgumentParser(
        description="DBML → Magento-style poster (.svg/.pdf) and interactive viewer (.html)",
    )
    parser.add_argument("dbml", nargs="?",
                        help="DBML file to render, or 'introspect' to read from a live database")
    parser.add_argument("introspect_dsn", nargs="?",
                        help="DSN for introspect: sqlite:///path.db | postgresql://... | mysql://...")
    parser.add_argument("-o", "--output", action="append",
                        help="output file(s): .html, .svg or .pdf (repeatable). Default: <name>.html and <name>.svg")
    parser.add_argument("--title")
    parser.add_argument("--hubs", type=int, default=6,
                        help="auto colour-code FKs into the N most-referenced tables")
    parser.add_argument("--aspect", type=float, default=1.414,
                        help="poster width/height target (A-series landscape = 1.414)")
    parser.add_argument("--keep-order", action="store_true",
                        help="keep DBML order inside panels instead of packing by size")
    parser.add_argument("--area", metavar="NAME",
                        help="render only tables in this area (v0.2)")
    args = parser.parse_args()

    if not args.dbml:
        parser.print_help()
        sys.exit(1)

    # ── introspect subcommand ─────────────────────────────────────────────────
    if args.dbml == "introspect":
        if not args.introspect_dsn:
            parser.error("introspect requires a DSN argument")
        from .introspect import introspect
        print(introspect(args.introspect_dsn))
        return

    # ── suggest-groups subcommand ─────────────────────────────────────────────
    if args.dbml == "suggest-groups":
        if not args.introspect_dsn:
            parser.error("suggest-groups requires a DBML file argument")
        from .suggest import suggest_groups
        try:
            with open(args.introspect_dsn, encoding="utf-8") as f:
                sc = parse_dbml(f.read())
        except FileNotFoundError:
            sys.exit(f"Error: could not find {args.introspect_dsn}")
        print(suggest_groups(sc))
        return

    # ── render ────────────────────────────────────────────────────────────────
    try:
        with open(args.dbml, encoding="utf-8") as f:
            sc = parse_dbml(f.read())
    except FileNotFoundError:
        sys.exit(f"Error: could not find {args.dbml}")

    if args.title:
        sc.title = args.title
    if not sc.tables:
        sys.exit("No tables found in the DBML file.")

    areas, area_color, hubs = resolve(sc, args.hubs)

    if not sc.groups:
        print(
            f"hint → no TableGroups found in {args.dbml}. "
            f"Run: dbml-atlas suggest-groups {args.dbml}",
            file=sys.stderr,
        )

    if args.area:
        _filter_area(sc, args.area)
        # Re-resolve with filtered schema
        areas, area_color, hubs = resolve(sc, args.hubs)

    root, area_boxes, legend, table_boxes = build_layout(sc, areas, area_color, hubs, args.aspect, args.keep_order)
    edges = route_edges(sc, table_boxes, hubs)

    stem = os.path.splitext(args.dbml)[0]
    outputs = args.output or [stem + ".html", stem + ".svg"]
    static_svg = None
    for out in outputs:
        ext = out.rsplit(".", 1)[-1].lower()
        if ext == "html":
            svg_markup, W, H = render_svg(sc, root, areas, area_boxes, legend, table_boxes, area_color, hubs, edges, True)
            doc = render_html(sc, svg_markup, W, H, areas, area_boxes, area_color, table_boxes, edges)
            with open(out, "w", encoding="utf-8") as output_file:
                output_file.write(doc)
            print(f"  viewer  → {out}")
        elif ext in ("svg", "pdf"):
            if static_svg is None:
                static_svg = render_svg(sc, root, areas, area_boxes, legend, table_boxes, area_color, hubs, edges, False)
            svg_markup, W, H = static_svg
            if ext == "svg":
                with open(out, "w", encoding="utf-8") as output_file:
                    output_file.write(svg_markup)
                print(f"  poster  → {out}  ({W}×{H})")
            else:
                via = write_pdf(svg_markup, W, H, out)
                print(f"  poster  → {out}  ({W}×{H}, via {via})")
        else:
            sys.exit(f"Unknown output type: {out} (use .html, .svg or .pdf)")
    print(f"{len(sc.tables)} tables · {len(edges)} FKs · {len(areas)} areas · {len(sc.groups)} groups")

if __name__ == "__main__":
    main()
